// Copies the pinned broker runtime into src/ for the ClojureScript build:
// shadow-cljs cannot require files outside its source roots, and vendor/
// must stay where the PINS test reads it. This file is gitignored and
// regenerated by the pretest hook and by build.mjs.
import { copyFile, mkdir } from "node:fs/promises";

await mkdir(new URL("../src/", import.meta.url), { recursive: true });
await copyFile(
  new URL("../vendor/kotoba-client-runtime.js", import.meta.url),
  new URL("../src/vendor-runtime.gen.js", import.meta.url),
);
